/* ===================== BÀI 27 · CMPS/SCAS và REP ===================== */
/* Bài 27 · CMPS/SCAS và REP (AMTS-EMB-002-M07-L03, X86-027) — sinh bởi tools/author/mpu8086/l27.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P27=[{"label": "Ví dụ: REPNE SCASB tìm một ký tự", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'HELLO'\nN       EQU     $-chuoi\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, chuoi               ; SCASB đọc ES:DI\n        MOV     CX, N\n        MOV     AL, 'L'                 ; khóa\n        REPNE   SCASB                   ; lặp khi CX <> 0 và AL <> [DI]\n        JNE     KHONG                   ; ZF = 0: hết chuỗi mà không thấy\n        LEA     AX, chuoi\n        SUB     DI, AX                  ; DI đã qua phần tử bằng khóa\n        MOV     DX, DI                  ; DL = vị trí tính từ 1\n        ADD     DL, '0'\n        JMP     INRA\nKHONG:  MOV     DL, '0'\nINRA:   MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "REPNE SCASB so AL = 'L' với H, E, L rồi dừng vì ZF = 1: 3 lần lặp, 9 + 15 × 3 = 54 chu kỳ trong một bước. Sau lệnh CX = 2, DI = 3 (đã qua chữ L đầu tiên) nên vị trí tính từ 1 là DI − offset chuoi = 3. Đoán trước: CX sau REPNE SCASB? Đáp án 0002h."}, {"label": "Ví dụ: REPE CMPSB so hai vùng nhớ", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmk      DB      'AMTS86'\nN       EQU     $-mk\nnhap    DB      'AMTX86'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     SI, mk\n        LEA     DI, nhap\n        MOV     CX, N\n        REPE    CMPSB                   ; lặp khi CX <> 0 và hai byte bằng\n        JE      BANG                    ; ZF = 1: cả N byte bằng nhau\n        MOV     DL, N\n        SUB     DL, CL                  ; vị trí khác đầu tiên = N - CX\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        JMP     XONG\nBANG:   MOV     DL, '='\n        MOV     AH, 02H\n        INT     21H\nXONG:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "REPE CMPSB so AMTS86 với AMTX86: ba cặp đầu bằng nhau, cặp thứ tư S/X khác nên dừng với ZF = 0, CX = 2. Vị trí khác đầu tiên = 6 − CX = 4. 9 + 22 × 4 = 97 chu kỳ. Đoán trước: sau REPE CMPSB, SI bằng bao nhiêu? Đáp án 0004h."}, {"label": "Lỗi: hỏi CX thay vì ZF sau REPNE", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'ABCDE'\nN       EQU     $-chuoi\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, chuoi\n        MOV     CX, N\n        MOV     AL, 'E'                 ; khóa ở phần tử cuối\n        REPNE   SCASB\n        JCXZ    KHONG                   ; LỖI: CX = 0 vẫn có thể là thấy\n        MOV     DL, 'Y'\n        JMP     INRA\nKHONG:  MOV     DL, 'N'\nINRA:   MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: khóa E nằm ở byte cuối. REPNE SCASB dừng với ZF = 1 và CX = 0 cùng lúc; JCXZ hiểu nhầm là không thấy nên in N. Sửa: JNE KHONG (hỏi ZF). Đoán trước: ngay sau REPNE SCASB, ZF bằng mấy? Đáp án 1."}, {"label": "Bẫy: CX = 0, cờ ZF còn sót", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      8 DUP(0)\ndai     DW      0                       ; chuỗi rỗng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        MOV     AL, 'A'\n        CMP     AL, 'A'                 ; một phép kiểm trước đó: ZF = 1\n        LEA     DI, buf\n        MOV     CX, dai                 ; CX = 0\n        REPNE   SCASB                   ; không so lần nào, cờ giữ nguyên\n        JE      THAY                    ; BẪY: ZF = 1 còn sót từ CMP\n        MOV     DL, 'N'\n        JMP     INRA\nTHAY:   MOV     DL, 'Y'\nINRA:   MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: dai = 0 nên CX = 0, REPNE SCASB không so lần nào (9 chu kỳ) và không đổi cờ. ZF = 1 còn lại từ CMP AL, 'A' nên JE nhảy và in Y dù vùng rỗng. Sửa: JCXZ KHONG trước REPNE SCASB. Đoán trước: sau REPNE SCASB, DI có đổi không? Đáp án không (0000h)."}, {"label": "Ví dụ: đo độ dài chuỗi kết thúc bằng $", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'MOV AX, 4C00h$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, chuoi\n        MOV     CX, 0FFFFH              ; giới hạn lớn: 65535 byte\n        MOV     AL, '$'\n        REPNE   SCASB                   ; dừng ngay sau dấu $\n        NOT     CX                      ; CX = số byte đã quét\n        DEC     CX                      ; bỏ dấu $: độ dài = 13\n        MOV     AX, CX\n        MOV     BL, 10\n        DIV     BL                      ; AL = chục, AH = đơn vị\n        ADD     AX, 3030H\n        MOV     DX, AX                  ; DL = chữ số hàng chục\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, DH\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Đo độ dài chuỗi 'MOV AX, 4C00h$' với giới hạn CX = FFFFh. REPNE SCASB quét 14 byte (cả dấu $), CX còn FFF1h; NOT CX = 000Eh, trừ 1 được 13 = 0Dh. DIV BL tách 1 và 3, in 13. Đoán trước: CX sau REPNE SCASB? Đáp án FFF1h."}, {"label": "Ví dụ: CMPSB và thứ tự từ điển", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      'ABD'\nb       DB      'ABC'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     SI, a                   ; nguồn: [SI]\n        LEA     DI, b                   ; đích: [DI]\n        MOV     CX, 3\n        REPE    CMPSB                   ; cờ theo [SI] - [DI]\n        JE      BANG\n        JA      LON                     ; không dấu: a > b\n        MOV     DL, '<'\n        JMP     INRA\nLON:    MOV     DL, '>'\n        JMP     INRA\nBANG:   MOV     DL, '='\nINRA:   MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "REPE CMPSB so ABD (nguồn, SI) với ABC (đích, DI): dừng ở byte thứ ba, cờ của 'D' − 'C': ZF = 0, CF = 0 nên JA nhảy và in >. Đổi chỗ hai chuỗi thì in <. Đoán trước: sau REPE CMPSB, CF bằng mấy? Đáp án 0."}, {"label": "Ví dụ: đếm số lần gặp bằng REPNE SCASB", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'BANANA ABBA'\nN       EQU     $-chuoi\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, chuoi\n        MOV     CX, N\n        MOV     AL, 'A'\n        XOR     BX, BX                  ; BX = số lần gặp\nTIEP:   JCXZ    HET                     ; hết vùng: không quét nữa\n        REPNE   SCASB\n        JNE     HET                     ; lần quét này không thấy\n        INC     BX                      ; thấy: DI, CX đã ở sau chỗ thấy\n        JMP     TIEP\nHET:    MOV     DL, BL\n        ADD     DL, '0'                 ; 5\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Đếm chữ A trong BANANA ABBA. Mỗi REPNE SCASB dừng ngay sau một chữ A; INC BX rồi quét tiếp từ DI, CX còn lại. Lần thứ năm thấy A ở byte cuối nên CX = 0 và JCXZ kết thúc. In 5. Đoán trước: sau lần REPNE SCASB đầu tiên, CX bằng bao nhiêu? Đáp án 0009h."}];
const sim27=makeX86Sim(document.getElementById("x86-l27"),{id:"s27",presets:P27,file:"BAI27.ASM"});
makeX86Ex(document.getElementById("ex-l27"),sim27,[{"t": "Vị trí đầu tiên bằng REPNE SCASB", "d": "Đọc 8 phím vào buf, rồi phím thứ 9 làm khóa (INT 21h hàm 08h). Dùng REPNE SCASB tìm lần xuất hiện ĐẦU TIÊN của khóa trong buf và in vị trí 1–8, hoặc 0 nếu không có. Ví dụ ABCDEFGHA in 1. Code mẫu sai ở cách nhận biết “không thấy”: sửa lại. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      8 DUP(0)\nN       EQU     $-buf\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, buf                 ; đọc 8 phím vào buf\n        MOV     CX, N\nDOC:    MOV     AH, 08H\n        INT     21H\n        STOSB\n        LOOP    DOC\n        MOV     AH, 08H                 ; phím thứ 9: khóa\n        INT     21H\n        LEA     DI, buf\n        MOV     CX, N\n        REPNE   SCASB\n        JCXZ    KHONG                   ; TODO: điều kiện \"không thấy\" đúng?\n        LEA     AX, buf\n        SUB     DI, AX\n        MOV     DX, DI\n        ADD     DL, '0'\n        JMP     INRA\nKHONG:  MOV     DL, '0'\nINRA:   MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDEFGHA", "out": "1"}, {"in": "ABCDEFGHH", "out": "8"}, {"in": "ABCDEFGHZ", "out": "0"}, {"in": "AAAAAAAAA", "out": "1"}, {"in": "123456785", "out": "5"}, {"in": "xyzxyzxyz", "out": "3"}]}, {"t": "So mật khẩu có giới hạn", "d": "Mật khẩu mk là 6 ký tự AMTS86. Đọc 6 phím (INT 21h hàm 08h) vào nhap, so với mk bằng một lệnh CMPSB có tiền tố lặp. In OK nếu cả 6 ký tự bằng nhau; ngược lại in SAI k với k (1–6) là vị trí khác đầu tiên. Code mẫu dùng sai tiền tố: sửa lại. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmk      DB      'AMTS86'\nN       EQU     $-mk\nnhap    DB      N DUP(0)\nsai     DB      'SAI $'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, nhap                ; đọc N phím\n        MOV     CX, N\nDOC:    MOV     AH, 08H\n        INT     21H\n        STOSB\n        LOOP    DOC\n        LEA     SI, mk\n        LEA     DI, nhap\n        MOV     CX, N\n        REPNE   CMPSB                   ; TODO: lặp tới khi nào?\n        JE      DUNG                    ; ZF = 1: cả N byte bằng nhau\n        LEA     DX, sai\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, N\n        SUB     DL, CL                  ; vị trí khác đầu tiên\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        JMP     XONG\nDUNG:   MOV     DL, 'O'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, 'K'\n        INT     21H\nXONG:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AMTS86", "out": "OK"}, {"in": "AMTS87", "out": "SAI 6"}, {"in": "BMTS86", "out": "SAI 1"}, {"in": "AMTX86", "out": "SAI 4"}, {"in": "amts86", "out": "SAI 1"}, {"in": "AMTS68", "out": "SAI 5"}]}, {"t": "Đếm ký tự nhanh", "d": "Đọc một phím khóa (INT 21h hàm 08h) rồi đếm số lần khóa xuất hiện trong chuỗi vb (52 ký tự, có sẵn) và in số đó bằng 2 chữ số (ví dụ 08). Code mẫu đọc từng byte bằng LODSB: đúng nhưng chậm. Viết lại phần đếm để chạy không quá 1600 chu kỳ ở test chậm nhất và mã không quá 56 byte. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nvb      DB      'THE 8086 HAS FOURTEEN REGISTERS AND A SIX BYTE QUEUE'\nN       EQU     $-vb\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        MOV     AH, 08H                 ; khóa\n        INT     21H\n        LEA     DI, vb\n        MOV     CX, N\n        XOR     BX, BX                  ; BX = số lần gặp\n        MOV     SI, DI                  ; đọc từng byte bằng LODSB\n        MOV     AH, AL\nDEM:    LODSB\n        CMP     AL, AH\n        JNE     KHAC\n        INC     BX\nKHAC:   LOOP    DEM\n        MOV     AX, BX                  ; in BX bằng 2 chữ số\n        AAM\n        ADD     AX, 3030H\n        MOV     DX, AX\n        XCHG    DL, DH\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, DH\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "E", "out": "08"}, {"in": "Z", "out": "00"}, {"in": "A", "out": "03"}, {"in": " ", "out": "09"}, {"in": "8", "out": "02"}, {"in": "Q", "out": "01"}, {"in": "S", "out": "04"}], "perf": {"cycles": 1600, "bytes": 56}}]);

makeQuiz("quiz27","score27",[{"q": "ES:DI trỏ vào chuỗi <code>ABCD<\/code> (offset 0), AL = 'C', CX = 4, DF = 0. Sau <code>REPNE SCASB<\/code>, CX, DI, ZF bằng bao nhiêu?", "o": ["CX = 1, DI = 3, ZF = 1", "CX = 2, DI = 2, ZF = 1", "CX = 1, DI = 2, ZF = 0", "CX = 0, DI = 4, ZF = 0"], "a": 0, "e": "So A, B, C: ba lần lặp, dừng vì ZF = 1 ở C. CX = 4 − 3 = 1; DI đã qua C nên = 3. CX = 0, DI = 4 là trường hợp không thấy."}, {"q": "Sau <code>REPE CMPSB<\/code> với CX ban đầu = 6, CX = 0. Kết luận nào đúng?", "o": ["Hai vùng chắc chắn bằng nhau vì đã so hết 6 cặp", "Chưa đủ: phải xem ZF, vì cặp thứ 6 có thể khác", "Hai vùng chắc chắn khác nhau vì CX đã về 0", "Chưa so cặp nào vì CX = 0 làm REPE dừng ngay"], "a": 1, "e": "CX = 0 chỉ cho biết đã so đủ 6 cặp; cặp cuối có thể bằng hoặc khác. Phải hỏi ZF (JE/JNE): ZF = 1 là cả 6 cặp bằng nhau, ZF = 0 là khác ở cặp thứ 6, như bài tập 2 với mật khẩu sai ở ký tự thứ 6."}, {"q": "Cần bỏ qua các dấu cách ở đầu một dòng (AL = ' '), dừng ở ký tự đầu tiên khác dấu cách. Dùng lệnh nào?", "o": ["<code>REPNE SCASB<\/code>", "<code>REPE SCASB<\/code>", "<code>REP MOVSB<\/code>", "<code>REPNE CMPSB<\/code>"], "a": 1, "e": "REPE lặp khi AL = [DI] (còn là dấu cách) và dừng ở byte khác đầu tiên. REPNE làm ngược lại: dừng ở dấu cách đầu tiên. REP MOVSB chỉ chép, không so."}, {"q": "ES:DI trỏ vào <code>'AB$'<\/code>. Đoạn code sau để lại CX bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     CX, 0FFFFH\n        MOV     AL, '$'\n        REPNE   SCASB\n        NOT     CX\n        DEC     CX<\/pre>", "o": ["0003h", "FFFCh", "0002h", "FFFDh"], "a": 2, "e": "Quét 3 byte (A, B, $): CX = FFFFh − 3 = FFFCh; NOT CX = 0003h; DEC còn 0002h, đúng bằng độ dài không kể dấu $."}, {"q": "DS:SI trỏ vào byte 'B', ES:DI trỏ vào byte 'A'. Sau <code>CMPSB<\/code>, lệnh nhảy nào được thực hiện?", "o": ["<code>JB<\/code>, vì cờ là của 'A' − 'B' < 0", "<code>JE<\/code>, vì CMPSB chỉ so sánh bằng nhau", "<code>JA<\/code>, vì cờ là của 'B' − 'A' > 0", "Không lệnh nào: CMPSB không đổi cờ"], "a": 2, "e": "CMPS đặt cờ theo nguồn − đích = DS:[SI] − ES:[DI] = 42h − 41h: CF = 0, ZF = 0 nên JA nhảy. Đây là thứ tự ngược với cách đọc “CMP đích, nguồn” quen thuộc nên dễ nhầm (Ví dụ 6)."}]);

